class LibraryMember {protected String memberId;protected int borrowLimit,borrowed;public LibraryMember(String id,int limit){if(id==null||id.trim().length()<4||limit<=0)throw new IllegalArgumentException();memberId=id;borrowLimit=limit;}public void borrowBook(){if(borrowed<borrowLimit)borrowed++;}public int getBooksBorrowed(){return borrowed;}public String displayInfo(){return "General Member | Books Borrowed: "+borrowed;}}
class StudentMember extends LibraryMember {protected String course;public StudentMember(String id,int limit,String c){super(id,limit);course=c;}@Override public String displayInfo(){return "Student Member | Course: "+course+" | Books Borrowed: "+borrowed;}}
public class Problem1_LibraryMembershipFoundation {static String enrollBatch(String[] ids,int limit){int ok=0,bad=0;for(String s:ids)try{new LibraryMember(s,limit);ok++;}catch(IllegalArgumentException e){bad++;}return "Enrolled: "+ok+" | Rejected: "+bad;}public static void main(String[]x){StudentMember s=new StudentMember("STU10",3,"CSE");s.borrowBook();s.borrowBook();System.out.println(s.getBooksBorrowed());System.out.println(enrollBatch(new String[]{"STU1","LB1","STU2"," ","STU3"},3));}}